import json,pathlib
R=[];D='AlexModGuy/DomesticationInnovation'
def a(f,m,o,b,l):R.append(dict(repo=D,file='/'+f+'.java',method=m,observation=o,application=b,limits=l))
a('TameableUtils','hasSameOwnerAsOneWay','兼容TamableAnimal与Mixin改造宠物两套owner，实体owner等于目标也同盟；第二分支内部却再次检tameable而非target是否TamableAnimal。','跨接口归属应双向审视，单向分支变量混用会漏同主关系。','完整多协议身份比较一处；双向包装hasSameOwnerAs、owner getter/setter不另计。')
a('TameableUtils','shouldUnloadToLantern','三态接口启用时只command2可卸到灯，否则遍历NBT尾缀Command且byte字段，找到用command1；无命令时原生宠物需非坐姿。','不同模组命令枚举不能按同一数值解释，失效/跟随判定应按实际所属协议。','实际宠物恢复/卸载资格策略一处，NBT扫描非通用基础设施独立凑数。')
a('TameableUtils','isTamed','Axolotl/Fox/Rabbit/Frog分别要求Mixin.isTame与对应配置开启，其他才接口或原生宠物isTame；注释明确运行绑定可能不齐。','存在owner字段不等于玩法许可有效，配置撤销也应改变控制关系。','完整身份启用判断，不将couldBeTamed或简单getOwnerOf适配器作为独立信用。')
a('TameableUtils','attractAnimals','每8tick按实体相位扫16/8范围不同owner且远于阈值的Animal，按距离取max，清target与lastHurtByMob再导航到宠物。','受控行为可重写其他生物的目标记忆，清target和受伤记忆是两个状态。','完整宠物herding实效调用；普通排序和范围数学不拆计。')
a('TameableUtils','aggroRandomMonsters','每400tick筛Monster、非同主、足够远且非旁观，20/8范围最近一个直接setTarget(attractor)。','诅咒诱敌可绕正常selector写目标，守卫必须在执行攻击时硬拒绝非Enemy。','实际INFAMY_CURSE入口调用，getTarget非空不是外部写入的授权证明。')
a('TameableUtils','scareRandomMonsters','按周期/受击/恐吓CD筛不同owner的Monster，粒子和CD按最近者处理，对全列表各找远离位置并强制导航；不清target。','驱散移动不等同撤攻击目标，不能以怪物转身判定归属伤害安全。','完整INTIMIDATION实效，一整段控制流计一处，粒子和向量基础设施不单计。')
a('TameableUtils','getAuraHealables','仅返回4格内同主、非旁观且HP未满的LivingEntity，为宠物治愈光环目标集合。','范围辅助效果也应逐目标核归属，不能按范围默认惠及其他玩家。','与getNearbyHealers反向查询合并同一治愈关系链，反向入口仅支持不计。')
a('TameableUtils','isValidTeleporter','要求TETHERED_TELEPORT；命令接口只认command2，原生Tamable则非坐姿且距owner小于10，其他false。','owner操作联动传送仍需宠物当前命令许可，单有附魔或UUID不够。','真实宠物主人传送资格，与卸载灯命令兼容策略用途不同；普通owner解析不计。')
a('MobMixin','di_tick','只服务端且isTamed时，AMPHIBIOUS水中保存原move/navigation并换水控制，出水或附魔撤销恢复；外层不tamed后未走恢复。','控制状态撤销需在身份失效路径也撤残余，不能把清理放在仍有效的外层条件内。','真实Mob.tick尾注入，不计通用水路寻路算法，借鉴生命周期守门顺序。')
a('MobMixin','di_pickUpItem','tamed且LINKED_INVENTORY才解析owner，玩家owner时先cancel原拾取，库存可装就discard掉落物，否则直接copyPosition给主人。','拾取者实体与物品所有权是两类权限，取消原处理后新副作用仍需检查。','实际宠物归属收益通道；本方法未查物品owner和pickupDelay，不声称其保护了陌生掉落。')
a('AxolotlAttackablesSensorMixin','di_isHuntTarget','仅改造宠物有owner且不驻留时，完全以isValidAttackTarget返回真/假覆盖原生感知；其他情况保留原版。','野生/已控制分支应显式分离，目标入口可复用统一授权谓词。','实际Mixin配置启用；Frog相似Sensor仅支持，不按端口增加计数。')
a('RecallBallEntity','interact','未finished且ownerUUID空直接discard；owner UUID等于实际交互玩家且尚未OPENED才打开球并SUCCESS。','恢复实体的归属资格以当前交互者UUID为准，空owner不能当作公开释放许可。','实际可交互球入口，interactAt仅转发不计，NBT访问器不计。')
a('RecallBallEntity','tick','OPENED动画满才服务端按存储实体类型create，读宠物保存数据并至少2或25%HP，入场后设FINISHED，关闭动画后discard。','延迟恢复通过序列化保留控制权，创建成功与入世界成功的提交边界需分别确认。','完整宠物复原状态机一处；addFreshEntity结果未检查，不能声称原子恢复。')
a('ChainLightningEntity','tick','Creator需Living才对current一次雷伤；链目标每tick扫8格Mob，拒Creator/同主/已电/盟友并查视线取最近，生成一次子链；到期移除。','初次current伤害不重查同盟而后继扫描会查，旧缓存关系改变需最终复核。','完整宠物链雷实际攻击行为；纯LOS几何不另计，伤害源lightningBolt并无creator归因。')
a('ChainLightningEntity','createLightningAt','子链复制previouslyShocked并加入新目标，复制creatorID/fromID/toID，剩链数减一后入世界。','派生攻击须继承owner与去重链，继承旧creator ID仍应核验有效性。','完整子攻击的授权上下文传递，与一般逐实体工厂不同；ID getter/setter不计。')
a('PsychicWallEntity','tick','服务端解析creator并同步ID，已死缩寿命至20；碰撞非同盟实体先push，弹体再按owner同主判是否反射，逐UUID15tick防重复，寿命结束删除。','友军弹体排反射发生在push之后，副作用安全边界要覆盖位移；失主也应明确处理。','完整宠物防护墙实效；isFiredByAlly/isSameTeam/碰撞包装全部并入同链不计。')
a('AmphibianFollowOwnerBehavior','tick','距离平方144以上尝试传送主人，否则按水陆与SPEEDSTER等级设置Brain walk/look记忆，而非单纯navigation.moveTo。','Brain记忆与Goal导航为不同缓存来源，停止租约应考虑旧Brain目标仍能驱动。','实际两栖宠物跟随Behavior；普通随机传送模板与清WALK_TARGET包装仅支持。')
a('AxolotlMixin','isValidAttackTarget','先isAlliedTo拒绝，仅目标等于owner的lastHurtMob或lastHurtByMob才通过，仍要求非同主/非盟友，其余false。','owner攻击快照也必须在最终使用时检查同盟，且不能替代王朝Enemy白名单。','完整宠物实际传感器谓词；Frog同方法标准化同构不计。')
a('FrogMixin','di_customServerAiStep','tame且有owner才继承主人最近攻击/受击的活体且非同主，逐分支同时setTarget和写Brain.ATTACK_TARGET，后受击分支覆盖前。','AI可有entity target和Brain target两份状态，清一份不等于停止实际攻击。','与Axolotl只写setTarget的入口合并，仅记本条双缓存控制链，不重复物种端口。')
a('FrogAiMixin','di_updateActivity','驻留强制FROG_STAY并cancel；跟随时活target写ATTACK_TARGET/NEAREST_ATTACKABLE并转TONGUE，否则按FOLLOW/TONGUE/繁殖等顺序选活动。','跟随模式仍能优先进入攻击活动，不能把following视为天然停止攻击。','真实Brain活动重选，makeBrain注册列表只支持，不把每个memory字段拆计。')
a('AxolotlAiMixin','di_updateActivity','仅当前非PLAY_DEAD且不playingDead时按命令覆盖；驻留改STAY，跟随允许PLAY_DEAD/FIGHT/FOLLOW优先序并cancel。','紧急防御活动与受控跟随互斥的优先级需保留，修复选敌不应无差别取消原生行为。','与Frog直接TONGUE缓存不同在PLAY_DEAD强优先门及FIGHT活动选择，不按速度/物种常量区分。')
a('RabbitMixin','removeUntamedGoals','先停止运行AvoidEntityGoal，再从goalSelector移除全部Avoid，targetSelector移除NearestAttackableTargetGoal；异常记录不继续伪称成功。','由野生转归属控制时必须撤老的目标生产者，停止运行和移除注册是两步。','真实宠物动态AI重组，不靠外观variant替换算另一案例。')
a('RabbitMixin','di_setRabbitType','HEAD取消原设置；EVIL时设置战斗属性并注册近战/反击，未驯服挂玩家与狼猎杀Goal，已驯服挂owner协防并移除野生Goal，最终写variant。','相同怪物类型可以因owner状态采用不同目标入口，保留野生行为需限定修复分支。','完整实际variant转换与宠物授权分支，属性数值与纯显示名字不是独立参考。')
a('ShootTongueMixin','di_eatEntity','tamed青蛙取消原吞食，取当前舌头目标，存活则doHurtTarget，死亡且Frog.canEat(frog)才remove KILLED。','捕获/吞食目标与普通getTarget不同，最终攻击门仍须核当前真实被害实体。','实际替换原生食物攻击路径；额外checkExtraStartConditions开放条件并入同链支持不计。')
a('PanicGoalMixin','di_canUse','原生PanicGoal入口若mob实现改造宠物接口且isTame，直接setReturnValue(false)，其余不取消。','已驯服控制身份能屏蔽野生恐慌入口，限定分支避免全局改变野生AI。','真实注入控制门非字段getter；canContinueToUse同条件端口不计。')
pathlib.Path(__file__).with_name('batch49.json').write_text(json.dumps(R,ensure_ascii=False,indent=2)+'\n')
